using System; using System.Drawing; using System.Windows.Forms; using FerramentaAFS.Localization;
namespace FerramentaAFS { public sealed class BatchProgressForm:Form { readonly Label label; readonly ProgressBar bar; public bool CancelRequested{get;private set;} public BatchProgressForm(string title,int total){var appIconPath=System.IO.Path.Combine(AppContext.BaseDirectory,"Images","icon.ico");if(System.IO.File.Exists(appIconPath))Icon=new Icon(appIconPath);Text=title;StartPosition=FormStartPosition.CenterParent;FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;MinimizeBox=false;ShowInTaskbar=false;ClientSize=new Size(560,125);label=new Label{Left=18,Top=18,Width=520,Height=34,Text=Loc.T("Processing"),AutoEllipsis=true};bar=new ProgressBar{Left=18,Top=58,Width=520,Height=22,Minimum=0,Maximum=Math.Max(1,total)};Button cancel=new Button{Left=418,Top=90,Width=120,Height=28,Text=Loc.T("Cancel")};cancel.Click+=(_,_)=>{CancelRequested=true;cancel.Enabled=false;};Controls.AddRange(new Control[]{label,bar,cancel});} public void Report(int current,string text){bar.Value=Math.Min(bar.Maximum,Math.Max(bar.Minimum,current));label.Text=text;label.Refresh();bar.Refresh();Application.DoEvents();} }
}
